// Pagination
const pag = document.createElement("div");
pag.className = "pagination";

const prevBtn = document.createElement("button");
prevBtn.className = "btn-secondary";
prevBtn.textContent = "← Prev";
prevBtn.disabled = state.cursorStack.length === 0;
prevBtn.addEventListener("click", () => {
  const prev = state.cursorStack.pop() ?? null;
  state.pageCursor = prev;
  loadBundles();
});
pag.appendChild(prevBtn);

const pageInfo = document.createElement("span");
pageInfo.style.fontSize = "13px";
pageInfo.style.color = "var(--p-color-text-subdued)";
pageInfo.textContent = `Total: ${state.totalCount}`;
pag.appendChild(pageInfo);

const nextBtn = document.createElement("button");
nextBtn.className = "btn-secondary";
nextBtn.textContent = "Next →";
nextBtn.disabled = !state.nextCursor;
nextBtn.addEventListener("click", () => {
  if (state.nextCursor) {
    if (state.pageCursor) state.cursorStack.push(state.pageCursor);
    state.pageCursor = state.nextCursor;
    loadBundles();
  }
});
pag.appendChild(nextBtn);

root.appendChild(pag);

new_string:
// Pagination
const pag = document.createElement("div");
pag.className = "pagination";

const totalPages = Math.ceil(state.totalCount / state.pageSize) || 1;

const prevBtn = document.createElement("button");
prevBtn.className = "btn-secondary";
prevBtn.textContent = "← Prev";
prevBtn.disabled = state.currentPage <= 1;
prevBtn.addEventListener("click", () => {
  if (state.currentPage > 1) {
    state.currentPage -= 1;
    loadBundles();
  }
});
pag.appendChild(prevBtn);

const pageInfo = document.createElement("span");
pageInfo.style.fontSize = "13px";
pageInfo.style.color = "var(--p-color-text-subdued)";
pageInfo.textContent = `Page ${state.currentPage} of ${totalPages} (${state.totalCount} total)`;
pag.appendChild(pageInfo);

const nextBtn = document.createElement("button");
nextBtn.className = "btn-secondary";
nextBtn.textContent = "Next →";
nextBtn.disabled = state.currentPage >= totalPages;
nextBtn.addEventListener("click", () => {
  if (state.currentPage < totalPages) {
    state.currentPage += 1;
    loadBundles();
  }
});
pag.appendChild(nextBtn);

root.appendChild(pag);
